function config(input, kind) {
  const c = { ...input, kind };
  if (!/^[\w-]{20,}$/.test(c.spreadsheet_id || '') || /REPLACE/.test(c.spreadsheet_id)) throw new Error('Set spreadsheet_id and create the input and Results tabs using the canvas headers.');
  c.max_items = bound(c.max_items, 1, kind === 'cluster' ? 30 : 10, 'max_items');
  c.run_id = new Date().toISOString();
  if (kind !== 'maps') { c.location = clean(c.location); c.gl = clean(c.gl).toLowerCase(); if (c.gl && !/^[a-z]{2}$/.test(c.gl)) throw new Error('gl must be blank or a two-letter country code.'); }
  if (kind === 'cluster') { c.min_results = bound(c.min_results, 3, 10, 'min_results'); c.shared_urls = bound(c.shared_urls, 2, 10, 'shared_urls'); if (c.shared_urls > c.min_results) throw new Error('shared_urls cannot exceed min_results'); }
  if (kind === 'publishers' || kind === 'markets') {
    c.max_pages = bound(c.max_pages, 1, 10, 'max_pages');
    c.content_selector = clean(c.content_selector) || 'main, article, [role="main"]';
    if (typeof c.js_rendering !== 'boolean') throw new Error('js_rendering must be true or false. Rendering can increase API cost.');
  }
  if (kind === 'publishers') {
    c.own_domain = host('https://' + clean(c.own_domain));
    c.brand_aliases = lines(c.brand_aliases); c.competitor_names = lines(c.competitor_names);
    c.excluded_domains = lines(c.excluded_domains).map(d => host('https://' + d));
    if (!c.own_domain || !c.brand_aliases.length || !c.competitor_names.length || c.excluded_domains.some(d => !d)) throw new Error('Set your bare domain, brand aliases, competitor names and valid excluded domains.');
    if ([...c.brand_aliases, ...c.competitor_names].some(s => s.length < 3 || s.length > 80)) throw new Error('Brand names must contain 3–80 characters.');
    c.content_selector = clean(c.content_selector) || 'main';
  }
  if (kind === 'markets') {
    c.location_b = clean(c.location_b); c.gl_b = clean(c.gl_b).toLowerCase();
    if (!c.location || !c.location_b || !/^[a-z]{2}$/.test(c.gl) || !/^[a-z]{2}$/.test(c.gl_b) || c.gl === c.gl_b) throw new Error('Set two canonical locations and different two-letter country codes. Both markets must use English queries.');
  }
  if (kind === 'maps') c.country_calling_code = String(bound(c.country_calling_code, 1, 999, 'country_calling_code'));
  return c;
}

function host(v) { return url(v)?.split('/')[2] || ''; }

function lines(v) { return [...new Set(String(v || '').split('\n').map(clean).filter(Boolean))]; }

function markets(c, searches, pages) {
  const ids = [...new Set(searches.map(s => s.topic_id))];
  return ids.map(id => {
    const a = searches.find(s => s.topic_id === id && s.market === 'A'), b = searches.find(s => s.topic_id === id && s.market === 'B');
    const good = a?.status === 'observed' && b?.status === 'observed' && a.returned >= 5 && b.returned >= 5;
    const urls = good ? overlap(a, b) : [];
    const domains = good ? [...new Set(a.results.map(r => host(r.url)))].filter(d => b.results.some(r => host(r.url) === d)) : [];
    const ownPages = pages.filter(p => [a, b].some(s => s?.results.some(r => r.url === p.url)));
    const bothRead = [a, b].every(s => s?.results.some(r => ownPages.some(p => p.url === r.url && p.page_status === 'read')));
    return row(c, key([id, a?.context, b?.context]), id, !good ? 'insufficient_serp_evidence' : bothRead ? 'ready_for_localization_review' : 'serp_only_review',
      good ? 'Compare intent and page formats before choosing one adapted page or separate market pages. URL overlap alone cannot decide.' : 'Failed or sparse market results; do not infer an intent difference.',
      { market_a: a, market_b: b, shared_urls: urls, shared_domains: domains, pages: ownPages.map(p => ({ url: p.url, status: p.page_status, reason: p.reason, title: p.title, h1: p.h1, excerpt: p.text.slice(0, 2500), excerpt_truncated: p.text.length > 2500 || p.truncated, metadata: p.page_metadata })),
        pages_not_read: [...new Set([...(a?.results || []), ...(b?.results || [])].map(r => r.url))].filter(u => !ownPages.some(p => p.url === u && p.page_status === 'read')),
        editorial_questions: ['Do both queries describe the same customer need?', 'Which local entities, terminology, currencies and page formats appear in the evidence?', 'Would one adapted page serve both markets, or does intent justify separate pages?', 'Which unvisited or truncated sources need checking?'],
        limits: 'English-language comparison, one response per query and market. This does not measure search demand, prove intent, or recommend hreflang implementation.' });
  });
}

function metadata(r) { const m = r?.requestMetadata || {}; return { id: clean(m.id), status: clean(m.status), html: clean(m.html), json: clean(m.json), search_url: clean(m.url) }; }

function overlap(a, b) { const s = new Set(b.results.map(r => r.url)); return a.results.map(r => r.url).filter(u => s.has(u)); }

function publishers(c, sources, pages, searches) {
  const result = searches.map(s => row(c, key(['prompt', c.own_domain, s.context]), s.query, s.status, 'AI Mode citation inventory; citations are not brand mentions.', s));
  for (const s of sources) {
    const p = pages.find(x => x.url === s.url);
    const known = p?.page_status === 'read';
    const own = known ? mentions(p.text, c.brand_aliases) : [], competitors = known ? mentions(p.text, c.competitor_names) : [];
    const ownLinks = known ? p.links.filter(u => domainMatches(host(u), c.own_domain)) : [];
    const status = s.status !== 'fetch' ? s.status : !known ? 'page_unavailable' : own.length || ownLinks.length ? 'brand_already_observed' : competitors.length ? 'review_publisher_fit' : 'no_competitor_evidence';
    result.push(row(c, key(['source', c.own_domain, s.url, c.location, c.gl]), s.url, status,
      status === 'review_publisher_fit' ? 'Competitors appear in the inspected text; verify publisher ownership, topical fit and full-page coverage before outreach.' : 'Review retained citation and page evidence. No contact discovery or messages are sent.',
      { source: s, page_status: p?.page_status || 'not_fetched', page_reason: p?.reason || '', title: p?.title || '', h1: p?.h1 || '', page_metadata: p?.page_metadata || {}, text_truncated: !!p?.truncated, own_mentions: own, competitor_mentions: competitors, own_links: ownLinks, links_truncated: !!p?.links_truncated, absence_note: 'No match in extracted content is not proof that the full page or publisher omits your brand. Known-domain exclusions do not establish independent ownership.', configured_brand_aliases: c.brand_aliases, configured_competitors: c.competitor_names }));
  }
  return result;
}

function row(c, id, topic, status, summary, evidence) {
  const extra = c.kind === 'cluster' ? {
    group_keywords: (evidence.cluster || []).join('\n'), returned_results: evidence.search?.returned || 0,
    cross_group_matches: (evidence.pairs || []).filter(p => !p.same_group && p.shared_urls.length >= c.shared_urls).map(p => p.query).join('\n'),
  } : c.kind === 'publishers' ? {
    citing_prompts: (evidence.source?.prompts || [evidence.query]).filter(Boolean).join('\n'),
    competitors_observed: (evidence.competitor_mentions || []).map(m => m.name + ' — ' + m.excerpt).join('\n'),
    brand_evidence: (evidence.own_mentions || []).map(m => m.excerpt).concat(evidence.own_links || []).join('\n'),
    source_url: evidence.source?.url || '',
  } : c.kind === 'maps' ? {
    differences: (evidence.fields || []).filter(f => f.status === 'review_difference').map(f => f.field + ': expected ' + f.expected + ' | observed ' + f.observed).join('\n'),
    unknown_fields: (evidence.fields || []).filter(f => f.status === 'unknown').map(f => f.field).join(', '),
    resolved_fields: (evidence.transitions || []).filter(f => f.resolved).map(f => f.field).join(', '), place_id: evidence.requested_place_id,
  } : {
    market_a_query: evidence.market_a?.query || '', market_b_query: evidence.market_b?.query || '',
    shared_url_count: status === 'insufficient_serp_evidence' ? '' : evidence.shared_urls.length,
    shared_domains: (evidence.shared_domains || []).join('\n'),
    page_samples: (evidence.pages || []).map(p => p.url + '\n' + p.status + ' | ' + p.title + '\n' + p.excerpt).join('\n\n'),
  };
  return { result_key: key([c.kind, id]), checked_at: c.run_id, topic, status, summary, ...extra, evidence_json: cell(evidence) };
}

function url(v) {
  const m = /^https?:\/\/([a-z0-9.-]+)(?::(443|80))?(\/[^\s#]*)?(?:#.*)?$/i.exec(clean(v));
  if (!m || !m[1].includes('.') || /^[\d.]+$/.test(m[1]) || /(^|\.)(localhost|local|internal|invalid|test)$/.test(m[1])) return '';
  const [path, query] = (m[3] || '/').split('?');
  const params = (query || '').split('&').filter(p => p && !/^(utm_[^=]*|gclid|fbclid)=/i.test(p)).sort();
  return 'https://' + m[1].toLowerCase().replace(/^www\./, '') + (path === '/' ? '/' : path.replace(/\/$/, '')) + (params.length ? '?' + params.join('&') : '');
}

function bound(v, min, max, name) { const n = Number(v); if (!Number.isInteger(n) || n < min || n > max) throw new Error(name + ' must be an integer from ' + min + ' to ' + max); return n; }

function cell(v) { const s = JSON.stringify(v); if (s.length > 44000) throw new Error('Evidence exceeds the Sheets cell limit. Reduce the batch size.'); return s; }

function citations(p, r) {
  const base = { ...p, metadata: metadata(r), references: [] };
  if (r.error || r.requestMetadata?.status !== 'ok' || !Array.isArray(r.references)) return { ...base, status: 'unknown' };
  base.references = r.references.map(x => ({ url: url(x.link || x.url), source_url: clean(x.link || x.url), title: clean(x.title) })).filter(x => x.url);
  return { ...base, status: base.references.length ? 'observed' : 'no_references_returned' };
}

function clean(v) { return typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : ''; }

function domainMatches(a, b) { return !!a && !!b && (a === b || a.endsWith('.' + b)); }

function key(parts) { return JSON.stringify(parts); }

function mentions(text, names) {
  return names.flatMap(name => {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = new RegExp('(?:^|[^\\p{L}\\p{N}])(' + escaped + ')(?=$|[^\\p{L}\\p{N}])', 'iu').exec(text);
    return m ? [{ name, excerpt: text.slice(Math.max(0, m.index - 100), m.index + name.length + 180) }] : [];
  });
}

return [{json:config($input.first().json,'maps')}];

function plan(c, rows) {
  const required = c.kind === 'maps' ? ['branch_id', 'place_id', 'expected_name', 'expected_address'] : c.kind === 'markets' ? ['topic_id', 'query_a', 'query_b'] : ['query'];
  const active = readRows(rows, required, required[0]);
  if (active.length > c.max_items) throw new Error('Input exceeds max_items. Select a smaller batch; rows are never silently dropped.');
  if (c.kind === 'maps' && new Set(active.map(r => clean(r.place_id))).size !== active.length) throw new Error('A place_id may only belong to one branch.');
  return active.flatMap(r => {
    if (c.kind === 'maps') {
      if (!/^[\w-]{10,}$/.test(clean(r.place_id))) throw new Error('Use the Google place ID, not a Maps URL or data ID.');
      return [{ ...r, context: key(['maps', clean(r.branch_id), clean(r.place_id), c.country_calling_code]) }];
    }
    const queries = c.kind === 'markets' ? [r.query_a, r.query_b] : [r.query];
    return queries.map((q, i) => {
      const query = clean(q); if (!query || query.length > 250) throw new Error('Queries must contain 1–250 characters.');
      const location = i ? c.location_b : c.location, gl = i ? c.gl_b : c.gl;
      const context = key([query, location, gl, 'desktop', c.kind === 'markets' ? 'en' : '']);
      return { query, topic_id: clean(r.topic_id), market: i ? 'B' : 'A', location, gl, context,
        fields: { deviceType: 'desktop', ...(location ? { location } : {}), ...(gl ? { gl } : {}), ...(c.kind === 'markets' ? { hl: 'en' } : {}) } };
    });
  });
}

function readRows(rows, required, idField) {
  const active = rows.filter(r => required.some(k => clean(String(r[k] ?? ''))));
  if (!active.length) throw new Error('No input rows. Required headers: ' + required.join(', '));
  const seen = new Set();
  for (const r of active) {
    if (required.some(k => !clean(String(r[k] ?? '')))) throw new Error('Incomplete input row. Required: ' + required.join(', '));
    const id = clean(String(r[idField])).normalize('NFKC').toLowerCase();
    if (seen.has(id)) throw new Error('Duplicate input identifier: ' + id); seen.add(id);
  }
  return active;
}

