  const result = searches.map(s => row(c, key(['prompt', c.own_domain, s.context]), s.query, s.status, 'AI Mode citation inventory; citations are not brand mentions.', s));
  for (const s of sources) {
    const p = pages.find(x => x.url === s.url);
    const known = p?.page_status === 'read';
    const own = known ? mentions(p.text, c.brand_aliases) : [], competitors = known ? mentions(p.text, c.competitor_names) : [];
    const ownLinks = known ? p.links.filter(u => domainMatches(host(u), c.own_domain)) : [];
    const status = s.status !== 'fetch' ? s.status : !known ? 'page_unavailable' : own.length || ownLinks.length ? 'brand_already_observed' : competitors.length ? 'review_publisher_fit' : 'no_competitor_evidence';
    result.push(row(c, key(['source', c.own_domain, s.url, c.location, c.gl]), s.url, status,
      status === 'review_publisher_fit' ? 'Competitors appear in the inspected text; verify publisher ownership, topical fit and full-page coverage before outreach.' : 'Review retained citation and page evidence. No contact discovery or messages are sent.',
