return plan($('Validate settings').first().json,$input.all().map(x=>x.json)).map(json=>({json}));

function previousRows(rows) {
  const seen = new Set();
  for (const r of rows.filter(r => r.result_key)) { if (seen.has(r.result_key)) throw new Error('Duplicate result_key in Results. Resolve before running.'); seen.add(r.result_key); }
  return rows;
}

previousRows($input.all().map(x=>x.json)); return $('Validate input batch').all().map(x=>({json:x.json}));

function mapsAudit(c, p, response, prior) {
  const place = response.placeResults, valid = !response.error && response.requestMetadata?.status === 'ok' && place?.placeId === clean(p.place_id);
  const fields = ['name', 'address', 'phone', 'website'];
  const values = { name: place?.title, address: place?.address, phone: place?.phone, website: place?.website };
  const comparisons = fields.map(field => {
    const expected = clean(String(p['expected_' + field] || '')), observed = clean(values[field]);
    const normalize = field === 'website' ? host : field === 'phone' ? v => phone(v, c.country_calling_code) : normalized;
    const alternatives = [expected, ...lines(p[field + '_aliases'])].filter(Boolean);
    const comparable = valid && expected && observed && normalize(observed) && normalize(expected);
    return { field, expected, observed: valid ? observed : '', alternatives,
      status: !expected ? 'not_configured' : !comparable ? 'unknown' : alternatives.some(v => normalize(v) === normalize(observed)) ? 'matches' : 'review_difference' };
  });
  const id = key([c.kind, p.context]); const old = prior.find(r => r.result_key === id);
  let before; if (old) { try { before = JSON.parse(old.evidence_json); } catch { throw new Error('Invalid saved listing evidence. Restore or clear that Results row.'); } }
  const transitions = comparisons.map(f => { const prev = before?.fields?.find(x => x.field === f.field); return { field: f.field, before: prev?.status || 'no_baseline', now: f.status, resolved: prev?.status === 'review_difference' && f.status === 'matches' && prev.expected === f.expected }; });
  const status = !valid ? 'identity_or_fetch_unknown' : comparisons.some(f => f.status === 'review_difference') ? 'differences_to_review' : comparisons.some(f => f.status === 'unknown') ? 'incomplete_listing' : 'configured_fields_match';
  return row(c, p.context, clean(p.branch_id), status, 'Compare owner-approved values with the exact place ID. Review differences; no Google Business Profile edits are made.',
    { requested_place_id: p.place_id, returned_place_id: place?.placeId || '', metadata: metadata(response), fields: comparisons, previous_checked_at: old?.checked_at || '', transitions,
      previous_fields: before?.fields || [], working_hours: place?.workingHours || null, hours_note: 'Hours are retained for manual review, not compared: holiday dates and time zones need owner confirmation.', website_note: 'Website comparison uses hostname only. Review paths, redirects, shared franchise domains and tracking URLs manually.' });
}

function metadata(r) { const m = r?.requestMetadata || {}; return { id: clean(m.id), status: clean(m.status), html: clean(m.html), json: clean(m.json), search_url: clean(m.url) }; }

function normalized(v) { return clean(v).normalize('NFKC').toLowerCase().replace(/[.,]/g, '').replace(/\s+/g, ' '); }

function phone(v, calling) { const raw = clean(String(v || '')); if (!raw || /(?:ext\.?|x|#)\s*\d/i.test(raw)) return ''; const digits = raw.replace(/\D/g, ''); if (digits.length < 7 || digits.length > 15) return ''; return raw.startsWith('+') ? digits : digits.startsWith('00') ? digits.slice(2) : digits.startsWith(calling) && digits.length > 10 ? digits : calling + digits.replace(/^0/, ''); }

function row(c, id, topic, status, summary, evidence) {
  const extra = c.kind === 'cluster' ? {
    group_keywords: (evidence.cluster || []).join('\n'), returned_results: evidence.search?.returned || 0,
    cross_group_matches: (evidence.pairs || []).filter(p => !p.same_group && p.shared_urls.length >= c.shared_urls).map(p => p.query).join('\n'),
  } : c.kind === 'publishers' ? {
    citing_prompts: (evidence.source?.prompts || [evidence.query]).filter(Boolean).join('\n'),
    competitors_observed: (evidence.competitor_mentions || []).map(m => m.name + ' — ' + m.excerpt).join('\n'),
    brand_evidence: (evidence.own_mentions || []).map(m => m.excerpt).concat(evidence.own_links || []).join('\n'),
    source_url: evidence.source?.url || '',
  } : c.kind === 'maps' ? {
    differences: (evidence.fields || []).filter(f => f.status === 'review_difference').map(f => f.field + ': expected ' + f.expected + ' | observed ' + f.observed).join('\n'),
    unknown_fields: (evidence.fields || []).filter(f => f.status === 'unknown').map(f => f.field).join(', '),
    resolved_fields: (evidence.transitions || []).filter(f => f.resolved).map(f => f.field).join(', '), place_id: evidence.requested_place_id,
  } : {
    market_a_query: evidence.market_a?.query || '', market_b_query: evidence.market_b?.query || '',
    shared_url_count: status === 'insufficient_serp_evidence' ? '' : evidence.shared_urls.length,
    shared_domains: (evidence.shared_domains || []).join('\n'),
    page_samples: (evidence.pages || []).map(p => p.url + '\n' + p.status + ' | ' + p.title + '\n' + p.excerpt).join('\n\n'),
  };
  return { result_key: key([c.kind, id]), checked_at: c.run_id, topic, status, summary, ...extra, evidence_json: cell(evidence) };
}

function url(v) {
  const m = /^https?:\/\/([a-z0-9.-]+)(?::(443|80))?(\/[^\s#]*)?(?:#.*)?$/i.exec(clean(v));
  if (!m || !m[1].includes('.') || /^[\d.]+$/.test(m[1]) || /(^|\.)(localhost|local|internal|invalid|test)$/.test(m[1])) return '';
  const [path, query] = (m[3] || '/').split('?');
  const params = (query || '').split('&').filter(p => p && !/^(utm_[^=]*|gclid|fbclid)=/i.test(p)).sort();
  return 'https://' + m[1].toLowerCase().replace(/^www\./, '') + (path === '/' ? '/' : path.replace(/\/$/, '')) + (params.length ? '?' + params.join('&') : '');
}

function cell(v) { const s = JSON.stringify(v); if (s.length > 44000) throw new Error('Evidence exceeds the Sheets cell limit. Reduce the batch size.'); return s; }

function clean(v) { return typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : ''; }

function host(v) { return url(v)?.split('/')[2] || ''; }

function key(parts) { return JSON.stringify(parts); }

function lines(v) { return [...new Set(String(v || '').split('\n').map(clean).filter(Boolean))]; }

function publishers(c, sources, pages, searches) {
  const result = searches.map(s => row(c, key(['prompt', c.own_domain, s.context]), s.query, s.status, 'AI Mode citation inventory; citations are not brand mentions.', s));
  for (const s of sources) {
    const p = pages.find(x => x.url === s.url);
    const known = p?.page_status === 'read';
    const own = known ? mentions(p.text, c.brand_aliases) : [], competitors = known ? mentions(p.text, c.competitor_names) : [];
    const ownLinks = known ? p.links.filter(u => domainMatches(host(u), c.own_domain)) : [];
    const status = s.status !== 'fetch' ? s.status : !known ? 'page_unavailable' : own.length || ownLinks.length ? 'brand_already_observed' : competitors.length ? 'review_publisher_fit' : 'no_competitor_evidence';
    result.push(row(c, key(['source', c.own_domain, s.url, c.location, c.gl]), s.url, status,
      status === 'review_publisher_fit' ? 'Competitors appear in the inspected text; verify publisher ownership, topical fit and full-page coverage before outreach.' : 'Review retained citation and page evidence. No contact discovery or messages are sent.',
      { source: s, page_status: p?.page_status || 'not_fetched', page_reason: p?.reason || '', title: p?.title || '', h1: p?.h1 || '', page_metadata: p?.page_metadata || {}, text_truncated: !!p?.truncated, own_mentions: own, competitor_mentions: competitors, own_links: ownLinks, links_truncated: !!p?.links_truncated, absence_note: 'No match in extracted content is not proof that the full page or publisher omits your brand. Known-domain exclusions do not establish independent ownership.', configured_brand_aliases: c.brand_aliases, configured_competitors: c.competitor_names }));
  }
  return result;
}

function citations(p, r) {
  const base = { ...p, metadata: metadata(r), references: [] };
  if (r.error || r.requestMetadata?.status !== 'ok' || !Array.isArray(r.references)) return { ...base, status: 'unknown' };
  base.references = r.references.map(x => ({ url: url(x.link || x.url), source_url: clean(x.link || x.url), title: clean(x.title) })).filter(x => x.url);
  return { ...base, status: base.references.length ? 'observed' : 'no_references_returned' };
}

function domainMatches(a, b) { return !!a && !!b && (a === b || a.endsWith('.' + b)); }

function mentions(text, names) {
  return names.flatMap(name => {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = new RegExp('(?:^|[^\\p{L}\\p{N}])(' + escaped + ')(?=$|[^\\p{L}\\p{N}])', 'iu').exec(text);
    return m ? [{ name, excerpt: text.slice(Math.max(0, m.index - 100), m.index + name.length + 180) }] : [];
  });
}

